package com.example.quanlybaotri.equipment.api;
import com.example.quanlybaotri.equipment.domain.*;import com.example.quanlybaotri.equipment.persistence.EquipmentRepository;import com.example.quanlybaotri.shared.api.ApiException;import jakarta.validation.Valid;import jakarta.validation.constraints.Size;import java.util.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/v1/equipment") public class InternalEquipmentController{private final EquipmentRepository repo;public InternalEquipmentController(EquipmentRepository repo){this.repo=repo;}@GetMapping("/{id}")@Transactional(readOnly=true)public EquipmentRef get(@PathVariable UUID id){return EquipmentRef.from(repo.findById(id).orElseThrow(()->ApiException.notFound("Không tìm thấy thiết bị")));}@PostMapping("/resolve")@Transactional(readOnly=true)public List<EquipmentRef>resolve(@Valid@RequestBody ResolveRequest r){return repo.findByIdIn(new LinkedHashSet<>(r.ids())).stream().map(EquipmentRef::from).toList();}public record ResolveRequest(@Size(max=500)List<UUID>ids){public ResolveRequest{ids=ids==null?List.of():List.copyOf(ids);}}public record EquipmentRef(UUID id,String assetCode,String name,UUID categoryId,String categoryName,UUID departmentId,EquipmentStatus status,boolean active){static EquipmentRef from(Equipment e){return new EquipmentRef(e.getId(),e.getAssetCode(),e.getName(),e.getCategory().getId(),e.getCategory().getName(),e.getDepartmentId(),e.getStatus(),e.isActive());}}}
